      <template v-else-if="route.name==='selectDate'"><div class="page-intro"><button class="back" @click="go('/setmeal')">← 返回选择套餐</button><p class="eyebrow">STEP 03 / 03</p><h1>选择体检日期</h1><p>{{selection.hospital?.name}} · {{selection.meal?.name}}</p></div><div class="steps"><span>✓ 选择机构</span><span>✓ 选择套餐</span><span class="current">03 选择日期</span></div><div class="calendar-card"><div class="calendar-head"><button @click="shiftMonth(-1)" aria-label="上个月">‹</button><strong>{{calendarYear}} 年 {{calendarMonth}} 月</strong><button @click="shiftMonth(1)" aria-label="下个月">›</button></div><div class="calendar-grid week"><span v-for="d in ['一','二','三','四','五','六','日']" :key="d">{{d}}</span></div><div v-if="loading" class="empty">正在加载日历…</div><div v-else class="calendar-grid"><span v-for="n in leadingDays" :key="'blank'+n"></span><button v-for="day in calendar" :key="day.date" :disabled="!day.available" :class="{chosen:selection.date===day.date}" @click="pickDate(day.date)"><span>{{Number(day.date.slice(-2))}}</span><small v-if="day.available">余 {{day.remaining}}</small><small v-else-if="day.capacity>0 && day.remaining===0">已满</small></button></div><p class="calendar-note">开放日期和每日名额由体检机构设置；提交预约时将再次检查。</p><button class="primary wide" :disabled="!selection.date" @click="go('/confirmOrder')">下一步 · 确认预约</button></div></template>
      <template v-else-if="route.name==='confirmOrder'"><div class="page-intro"><button class="back" @click="go('/selectDate')">← 返回选择日期</button><p class="eyebrow">REVIEW YOUR APPOINTMENT</p><h1>确认预约信息</h1><p>请核对以下信息后提交预约。</p></div><div class="confirm-card"><div class="card-title">体检人信息</div><div class="info-row"><span>体检人</span><strong>{{selection.patient?.patientName || user?.realName}}（{{selection.patient?.patientType===2?'家属':'本人'}}）</strong></div><div class="info-row"><span>性别</span><strong>{{(selection.patient?.patientSex ?? user?.sex)===0?'女':'男'}}</strong></div><div class="info-row"><span>出生日期</span><strong>{{selection.patient?.patientType===2 ? selection.patient?.patientBirthday : user?.birthday}}</strong></div><div class="info-row"><span>身份证号</span><strong>{{maskId(selection.patient?.patientType===2 ? selection.patient?.patientIdentityCard : user?.identityCard)}}</strong></div><div class="info-row"><span>预约账号</span><strong>{{user?.userId}}</strong></div><div class="card-title">预约详情</div><div class="info-row"><span>体检机构</span><strong>{{selection.hospital?.name}}</strong></div><div class="info-row"><span>体检套餐</span><strong>{{selection.meal?.name}}</strong></div><div class="info-row"><span>体检日期</span><strong>{{selection.date}}</strong></div><div class="total-row"><span>套餐价格</span><strong>¥ {{selection.meal?.price}}</strong></div><button class="primary wide" :disabled="busy || !selection.date" @click="submitOrder">{{busy?'提交中…':'确认预约'}}</button></div></template>
      <template v-else-if="route.name==='appointmentSuccess'"><div class="success-card"><img class="success-tips" src="/img/tips.png" alt="温馨提示"><div class="success-mark">✓</div><p class="eyebrow">APPOINTMENT CONFIRMED</p><h1>预约提交成功</h1><p class="muted">请在预约日期前往体检机构。</p><button class="primary" @click="go('/appointmentList')">查看我的预约 →</button><button class="back" @click="go('/home')">返回首页</button></div></template>
      <template v-else-if="route.name==='appointmentList' || route.name==='reportList'"><div class="page-intro"><p class="eyebrow">{{route.name==='reportList'?'YOUR HEALTH RECORDS':'YOUR APPOINTMENTS'}}</p><h1>{{route.name==='reportList'?'体检报告':'我的预约'}}</h1><p>{{route.name==='reportList'?'查看已归档的体检报告。':'查看并管理您的体检预约。'}}</p></div><div v-if="route.name==='appointmentList'" class="tabs"><button :class="{active:orderState===1}" @click="changeOrderState(1)">未归档</button><button :class="{active:orderState===2}" @click="changeOrderState(2)">已归档</button></div><div v-if="loading" class="empty">正在加载…</div><div v-else-if="!orders.length" class="empty"><i class="fa fa-calendar-o"></i><p>暂无{{route.name==='reportList'?'体检报告':'预约记录'}}</p><button class="outline" @click="go('/appointment')">去预约体检</button></div><div v-else class="order-list"><article v-for="o in orders" :key="o.orderId" class="order-card"><div class="order-top"><span>预约编号 #{{o.orderId}}</span><span class="pill" :class="{soft:o.state===2}">{{o.state===1?'未归档':'已归档'}}</span></div><div class="order-content"><div><h3>{{o.mealName || '体检套餐'}}</h3><p>体检人：{{o.patientName || user?.realName}}（{{o.patientType===2?'家属':'本人'}}）</p><p>{{o.hospitalName || '体检机构'}} · {{o.orderDate}}</p></div><button v-if="o.state===2" class="outline" @click="openReport(o)">查看报告 →</button><button v-else class="text-danger" @click="cancelOrder(o)">取消预约</button></div></article></div></template>
      <template v-else-if="route.name==='report'"><div class="page-intro"><button class="back" @click="go('/reportList')">← 返回报告列表</button><p class="eyebrow">EXAMINATION REPORT</p><h1>体检报告</h1><p>预约编号 #{{reportOrderId}} · 体检人：{{reportOrder?.patientName || user?.realName}} · 检查结果与总检结论</p></div><div v-if="loading" class="empty">正在加载报告…</div><template v-else><section v-if="reportOrder" class="report-panel"><h2>免费在线咨询</h2><p class="muted" style="margin:14px 0">对报告有疑问？提交问题并查看回复。</p><button class="primary" @click="router.push({name:'consultation',query:{orderId:reportOrderId}})">咨询报告 →</button></section><section class="report-panel"><h2>异常项目</h2><div v-if="!abnormalItems.length" class="muted report-empty">暂无标记为异常的检查项</div><div v-for="d in abnormalItems" :key="d.cidrId" class="result-row"><div><strong>{{d.name}}</strong><small>{{d.itemName}}{{d.normalValueString ? ' · 参考范围：'+d.normalValueString : ''}} {{d.unit || ''}}</small></div><span class="abnormal">{{d.value || '未填写'}} · 异常</span></div></section><section class="report-panel"><h2>总检结论</h2><div v-if="!conclusions.length" class="muted report-empty">暂无总检结论</div><div v-for="o in conclusions" :key="o.orId" class="result"><h3>{{o.title}}</h3><p>{{o.content || '暂无内容'}}</p></div></section><section class="report-panel"><h2>检查结果</h2><div v-if="!reports.length" class="muted report-empty">暂无检查结果</div><article v-for="r in reports" :key="r.cirId" class="report-item"><h3>{{r.ciName}}</h3><div v-if="!r.details.length" class="muted">暂无明细</div><div v-for="d in r.details" :key="d.cidrId" class="result-row"><div><strong>{{d.name}}</strong><small>{{d.normalValueString ? '参考范围：'+d.normalValueString : ''}} {{d.unit || ''}}</small></div><span :class="{abnormal:d.isError===1}">{{d.value || '未填写'}} {{d.isError===1?'· 异常':''}}</span></div></article></section></template></template>
      <DoctorAppointments v-else-if="route.name==='doctorAppointments'"/><Consultation v-else-if="route.name==='consultation'"/><HealthTools v-else-if="route.name==='assessments'"/><HealthNews v-else-if="route.name==='healthNews'"/><template v-else-if="route.name==='doctors'"><div class="page-intro"><button class="back" @click="go('/home')">← 返回首页</button><p class="eyebrow">HEALTH TEAM</p><h1>医生介绍</h1><p>了解体检团队的服务方向。</p></div><div class="doctors-page"><button v-for="d in doctors" :key="d.id" class="doctor-profile-card" @click="openDoctor(d)"><img class="doctor-photo" :src="d.photo" :alt="d.name + '照片'"><span class="doctor-copy"><strong>{{d.name}}</strong><small>{{d.department}} · {{d.title}}</small><em>{{d.summary}}</em></span><b>查看介绍 →</b></button></div></template>
      <template v-else-if="route.name==='doctor'"><div class="page-intro"><button class="back" @click="go('/doctors')">← 返回医生列表</button><p class="eyebrow">DOCTOR PROFILE</p><h1>医生介绍</h1></div><article v-if="selectedDoctor" class="doctor-detail"><div class="doctor-detail-head"><img class="doctor-photo large" :src="selectedDoctor.photo" :alt="selectedDoctor.name + '照片'"><div><h2>{{selectedDoctor.name}}</h2><p>{{selectedDoctor.department}} · {{selectedDoctor.title}}</p></div></div><section><h3>医生简介</h3><p>{{selectedDoctor.introduction}}</p></section><section><h3>服务方向</h3><div class="specialty-tags"><span v-for="item in selectedDoctor.specialties" :key="item">{{item}}</span></div></section><section><h3>预约须知</h3><p>请选择日期提交预约，系统将生成当日排队号；实际出诊安排以机构确认为准。</p></section><button class="primary" @click="router.push({name:'doctorAppointments',query:{id:selectedDoctor.id}})">预约医生并排号 →</button> <button class="outline" @click="go('/doctors')">查看其他医生</button></article><div v-else class="empty">未找到相关医生 <button class="back" @click="go('/doctors')">返回医生列表</button></div></template>
      <template v-else-if="route.name==='personal'"><div class="page-intro"><p class="eyebrow">MY ACCOUNT</p><h1>个人中心</h1><p>管理您的个人信息和体检记录。</p></div><div class="personal-card"><div class="personal-user"><img class="avatar large" src="/img/user.png" alt=""><div><h2>{{user?.realName}}</h2><p>{{user?.userId}}</p></div></div><div class="personal-links"><button @click="go('/appointmentList')">我的预约 <span>→</span></button><button @click="go('/reportList')">体检报告 <span>→</span></button><button @click="go('/consultation')">我的咨询 <span>→</span></button><button @click="go('/doctorAppointments')">医生预约 <span>→</span></button><button @click="logout">退出登录 <span>→</span></button></div></div></template>
